function setStoreNavigationData(environments=[],subcategories=[]){
 const activeEnvironments=environments.filter(item=>item.active!==false).sort((a,b)=>Number(a.sort_order)-Number(b.sort_order));
 const activeSubcategories=subcategories.filter(item=>item.active!==false&&item.environment_id);
 if(activeEnvironments.length&&activeSubcategories.length){
  const next=activeEnvironments.map(environment=>({
   id:environment.id,name:environment.name,slug:environment.slug,description:environment.description||`Encontre tudo para ${environment.name.toLowerCase()}`,
   image:environment.image_url||environment.image||'',icon_key:environment.icon_key||'',subcategories:activeSubcategories.filter(item=>String(item.environment_id)===String(environment.id)).sort((a,b)=>Number(a.sort_order)-Number(b.sort_order)).map(item=>({id:item.id,name:item.name,slug:item.slug,icon_key:item.icon_key||'',keywords:item.search_keywords||''}))
  })).filter(item=>item.subcategories.length);
  if(next.length)environmentNavigation=next;
 }
 const active=environmentRecord(activeEnvironment);if(active)activeEnvironment=active.name;else{activeEnvironment='Todas';activeSubcategory=''}
 renderEnvironmentNavigation();renderCats();renderCatalog();
}
