function productCode(p){return p.sku||(p.dbId?'':`MOV-${String(p.id).padStart(4,'0')}`)}
function productHasPrice(p){return Number.isFinite(Number(p?.price))&&Number(p.price)>0}
function productPriceText(p){return productHasPrice(p)?brl(p.price):'Consulte o preço'}
function productInStock(p){return Boolean(p?.dbId&&Number(p.stock)>0)}
function productCanBuy(p){return productInStock(p)&&p.whatsappEnabled!==false&&productHasPrice(p)}
function productWhatsAppButton(p,detail=false){if(!p.dbId||p.whatsappEnabled===false||(!detail&&!productCanBuy(p)))return '';const outOfStock=!productInStock(p),inquiry=!productCanBuy(p);const label=outOfStock?'CONSULTAR DISPONIBILIDADE':inquiry?'CONSULTAR PREÇO':commerceSettings.buttonText;const subtitle=inquiry?'Fale com a loja antes de comprar':commerceSettings.buttonSubtitle;return `<button class="product-whatsapp${detail?' detail-whatsapp':''}${inquiry?' is-inquiry':''}" type="button" onclick="buyProductWhatsApp(${p.id})">${storeIcon('whatsapp')}<span><b>${storeHtml(label)}</b><small>${storeHtml(subtitle)}</small></span>${storeIcon('arrow')}</button>`}
function productBenefitSeals(p){return [p.freeCityShipping?'<span class="detail-benefit-seal"><img src="assets/seal-free-shipping.png" alt="Frete grátis"></span>':'',p.freeAssembly?'<span class="detail-benefit-seal is-assembly"><img src="assets/seal-free-assembly.png" alt="Armação gratuita"></span>':''].join('')}
function productSpecificationEntries(p){const entries=Object.entries(p.specifications||{});[['Medidas',p.dimensions],['Material',p.material],['Cores',p.color],['Garantia',p.warranty]].forEach(([label,value])=>{if(value&&!entries.some(([key])=>key.toLowerCase()===label.toLowerCase()))entries.push([label,value])});return entries.filter(([,value])=>value!=null&&String(value).trim()!=='')}
function productUrl(p){const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('product',p.dbId||p.id);return url.href}
function whatsappUrl(message){return commerceSettings.whatsapp?`https://wa.me/${commerceSettings.whatsapp}?text=${encodeURIComponent(message)}`:''}
function openWhatsAppMessage(message){const url=whatsappUrl(message);if(!url){toast('WhatsApp da loja ainda não foi configurado.');return false}window.open(url,'_blank','noopener,noreferrer');return true}
function buyProductWhatsApp(id){const p=products.find(item=>item.id===id);if(!p?.dbId||p.whatsappEnabled===false){toast('Produto indisponível para atendimento no momento.');return}const outOfStock=!productInStock(p),missingPrice=!productHasPrice(p);const message=`Olá! Tenho interesse neste produto:\n\n${p.n}\n\nPreço: ${productPriceText(p)}\nCategoria: ${p.cat}${outOfStock?'\nDisponibilidade: indisponível no momento':''}\n\n${productUrl(p)}\n\n${outOfStock?'Gostaria de consultar a disponibilidade e saber mais informações.':missingPrice?'Gostaria de consultar o preço e saber mais informações.':'Gostaria de saber mais informações.'}`;if(openWhatsAppMessage(message))window.dispatchEvent(new CustomEvent('atacarejo:whatsapp-product-click',{detail:{productId:p.dbId,productName:p.n,category:p.cat,price:p.price,action:outOfStock?'availability_inquiry':missingPrice?'price_inquiry':'purchase_interest',source:'site'}}))}
function buyCartWhatsApp(){const items=cart.map(item=>({item,product:products.find(product=>product.id===item.id)})).filter(entry=>productInStock(entry.product)&&entry.product.cartEnabled!==false&&productHasPrice(entry.product)&&entry.item.qty<=Number(entry.product.stock));if(!items.length)return toast('Sua sacola não tem produtos disponíveis no momento.');const total=items.reduce((sum,{item,product})=>sum+item.qty*product.price,0);const lines=items.map(({item,product})=>{const code=productCode(product);return `${item.qty}x ${product.n}${code?`\nCódigo: ${code}`:''}\n${productPriceText(product)}`}).join('\n\n');openWhatsAppMessage(`${commerceSettings.message}\n\nMontei uma sacola no site e tenho interesse nestes produtos:\n\n${lines}\n\nTotal dos produtos: ${brl(total)}\n\nGostaria de verificar disponibilidade e finalizar minha compra.`)}
  function officialProductCard(p){
    const hasPrice=productHasPrice(p);
    const campaign=p.campaign===true||p.badge==='Campanha';
    const oldPrice=hasPrice&&Number.isFinite(Number(p.old))&&Number(p.old)>Number(p.price)?`<span class="official-product-old">${brl(p.old)}</span>`:'';
    const description=p.description?`<p class="official-product-description">${storeHtml(p.description)}</p>`:'';
    const installments=hasPrice&&Number.isFinite(p.installmentCount)&&Number.isFinite(p.installmentValue)&&p.installmentCount>0&&p.installmentValue>0?`<b>ou ${p.installmentCount}x de ${brl(p.installmentValue)}</b>`:'';
    const photoBenefits=[p.freeCityShipping?'<span class="photo-benefit is-shipping"><img src="assets/seal-free-shipping.png" alt="Frete grátis"></span>':'',p.freeAssembly?'<span class="photo-benefit is-assembly"><img src="assets/seal-free-assembly.png" alt="Armação gratuita"></span>':''].join('');
     const whatsapp=productWhatsAppButton(p);
     const bag=p.cartEnabled!==false&&hasPrice&&productInStock(p)?`<button class="product-add-bag" type="button" onclick="addCart(${p.id})">${storeIcon('bag')}<span>Adicionar à sacola</span></button>`:'';
    const taxonomyLabel=[p.environment,p.subcategory].filter(Boolean).join(' · ')||p.cat;
    return `<article class="official-product-card catalog-card product-card" data-product-id="${p.id}" tabindex="0" aria-label="Ver detalhes de ${storeHtml(p.n)}"><div class="official-product-photo"><img src="${storeHtml(p.img)}" alt="${storeHtml(p.n)}" loading="lazy" width="800" height="580">${campaign?'<span class="campaign-badge">Campanha</span>':''}<button class="official-product-heart ${favs.includes(p.id)?'active':''}" type="button" onclick="toggleFav(${p.id})" aria-label="${favs.includes(p.id)?'Remover dos':'Adicionar aos'} favoritos">${storeIcon('heart')}</button>${photoBenefits?`<div class="photo-benefits">${photoBenefits}</div>`:''}</div><div class="official-product-body"><small class="official-product-category">${CategoryIcons.icon(p.categoryIconKey||p.subcategory||p.environment||p.cat,{environment:p.environment,size:18})}${storeHtml(taxonomyLabel)}</small><h3>${storeHtml(p.n)}</h3>${description}<div class="official-product-price">${oldPrice}<strong class="${hasPrice?'':'price-on-request'}">${productPriceText(p)}</strong>${hasPrice?`<em>à vista no Pix ou cartão${installments}</em>`:''}</div><div class="official-product-benefits"><span>${storeIcon('shield')}<b>${storeHtml(commerceSettings.secureBenefit)}</b></span><span>${storeIcon('store')}<b>${storeHtml(commerceSettings.pickupBenefit)}</b></span><span>${storeIcon('pin')}<b>${storeHtml(commerceSettings.serviceRegion)}</b></span></div><div class="official-product-actions">${whatsapp}${bag}</div></div></article>`
  }
