function initCategoryCarousel(){const row=document.querySelector('#categoryRow');const prev=document.querySelector('.category-prev');const next=document.querySelector('.category-next');if(!row||!prev||!next)return;const amount=()=>Math.max(row.clientWidth*.82,260);prev.onclick=()=>row.scrollBy({left:-amount(),behavior:'smooth'});next.onclick=()=>row.scrollBy({left:amount(),behavior:'smooth'});let dragging=false,dragged=false,startX=0,startScroll=0;row.addEventListener('mousedown',e=>{if(e.button!==0)return;dragging=true;dragged=false;startX=e.clientX;startScroll=row.scrollLeft;row.classList.add('is-dragging')});row.addEventListener('mousemove',e=>{if(!dragging)return;const distance=e.clientX-startX;if(Math.abs(distance)>8)dragged=true;row.scrollLeft=startScroll-distance;if(dragged)e.preventDefault()});const stop=()=>{dragging=false;row.classList.remove('is-dragging')};window.addEventListener('mouseup',stop);row.addEventListener('mouseleave',stop);row.addEventListener('click',e=>{if(!dragged)return;e.preventDefault();e.stopPropagation();dragged=false},true)}
