function filterEnvironment(value){
 const environment=environmentRecord(value);offersOnly=false;activeEnvironment=environment?.name||'Todas';activeSubcategory='';activeCat=activeEnvironment;clearCatalogSearch();renderCatalog();closeEnvironmentNavigation();window.MobileNav?.mark('categorias');document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'});
}
function filterSubcategory(environmentValue,subcategory){
 const environment=environmentRecord(environmentValue);if(!environment)return;
 offersOnly=false;activeEnvironment=environment.name;activeSubcategory=subcategory;activeCat=subcategory;clearCatalogSearch();renderCatalog();closeEnvironmentNavigation();window.MobileNav?.mark('categorias');document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'});
}
function filterCategory(value){
 if(value==='Todas')return filterEnvironment('Todas');
 const environment=environmentRecord(value);if(environment)return filterEnvironment(environment.name);
 const owner=environmentNavigation.find(item=>item.subcategories.some(subcategory=>normaliseSearch(subcategoryName(subcategory))===normaliseSearch(value)));
 if(owner){const match=owner.subcategories.find(item=>normaliseSearch(subcategoryName(item))===normaliseSearch(value));return filterSubcategory(owner.name,subcategoryName(match))}
 return filterEnvironment(value);
}
function showOffers(){offersOnly=true;activeCat='Todas';activeEnvironment='Todas';activeSubcategory='';clearCatalogSearch();renderCatalog();closeEnvironmentNavigation();window.MobileNav?.mark('ofertas');document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'})}
function addCart(id){const p=products.find(x=>x.id===id);if(!productInStock(p)||p.cartEnabled===false||!productHasPrice(p))return toast('Produto indisponível para compra no momento.');const item=cart.find(x=>x.id===id);if(item&&item.qty>=Number(p.stock))return toast(`Estoque máximo disponível: ${p.stock}.`);item?item.qty++:cart.push({id,qty:1});save();window.MobileNav?.cartAdded();toast('Produto adicionado à sacola');}
function toggleFav(id){favs.includes(id)?favs=favs.filter(x=>x!==id):favs.push(id);localStorage.setItem('movel-favs',JSON.stringify(favs));render();toast(favs.includes(id)?'Adicionado aos favoritos':'Removido dos favoritos')}
function save(){cart=cart.map(item=>({id:Number(item.id),qty:Math.max(1,Math.floor(Number(item.qty)||1))}));localStorage.setItem('movel-cart',JSON.stringify(cart));updateCounts()};function updateCounts(){let n=cart.reduce((s,i)=>s+i.qty,0);document.querySelectorAll('#cartCount,#cartBadge,#mobileBadge').forEach(e=>e.textContent=e.id==='cartCount'?`${n} item${n!==1?'s':''}`:n);const favCount=document.querySelector('#favCount');if(favCount)favCount.textContent=`${favs.length} item${favs.length!==1?'s':''}`}
function toast(t){let e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
let drawerReturnFocus=null,drawerHistoryPushed=false;
function openDrawer(html){const drawer=document.querySelector('#drawer');const wasOpen=drawer.classList.contains('open');if(!wasOpen)drawerReturnFocus=document.activeElement;document.querySelector('#drawerContent').innerHTML=html;drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');const routeDrawer=Boolean(window.MobileNav?.controlsDrawer());drawer.classList.toggle('mobile-route-drawer',routeDrawer);drawer.setAttribute('aria-modal',routeDrawer?'false':'true');document.body.classList.toggle('mobile-route-drawer',routeDrawer);if(!wasOpen&&!routeDrawer){history.pushState({...history.state,storeDrawer:true},'');drawerHistoryPushed=true}else if(routeDrawer)drawerHistoryPushed=false;requestAnimationFrame(()=>drawer.querySelector('.close')?.focus())}
function closeDrawer(fromHistory=false){const drawer=document.querySelector('#drawer');if(!drawer.classList.contains('open'))return;const routeDrawer=drawer.classList.contains('mobile-route-drawer');drawer.classList.remove('open','product-detail-open','checkout-open','mobile-route-drawer');drawer.setAttribute('aria-hidden','true');drawer.setAttribute('aria-modal','true');document.body.classList.remove('modal-open','mobile-route-drawer');document.querySelector('.menu')?.setAttribute('aria-expanded','false');if(routeDrawer&&!fromHistory)window.MobileNav?.returnFromDrawer();else if(!fromHistory&&drawerHistoryPushed&&history.state?.storeDrawer){drawerHistoryPushed=false;history.back()}else drawerHistoryPushed=false;drawerReturnFocus?.focus?.();drawerReturnFocus=null}
function cartDetails(){return cart.map(item=>({item,product:products.find(product=>product.id===item.id)})).filter(entry=>entry.product)}
function cartTotals(entries=cartDetails()){const regular=entries.reduce((sum,{item,product})=>sum+item.qty*(Number(product.old)>Number(product.price)?Number(product.old):Number(product.price)),0);const subtotal=entries.reduce((sum,{item,product})=>sum+item.qty*Number(product.price||0),0);return{regular,subtotal,discount:Math.max(0,regular-subtotal)}}
function changeCartQuantity(id,delta){const item=cart.find(entry=>entry.id===id),product=products.find(entry=>entry.id===id);if(!item||!product)return;if(delta>0&&item.qty>=Number(product.stock||0))return toast(`Estoque máximo disponível: ${product.stock}.`);if(item.qty+delta<1)return removeCart(id);item.qty+=delta;save();openCart()}
function openCart(){window.MobileNav?.mark('sacola');document.querySelector('#drawer')?.classList.remove('checkout-open','product-detail-open');const entries=cartDetails();const totals=cartTotals(entries);const invalid=entries.some(({item,product})=>!productInStock(product)||product.cartEnabled===false||!productHasPrice(product)||item.qty>Number(product.stock));const lines=entries.map(({item,product})=>{const unavailable=!productInStock(product)||product.cartEnabled===false||!productHasPrice(product);const old=Number(product.old)>Number(product.price)?`<del>${brl(product.old)}</del>`:'';return `<article class="cart-item ${unavailable?'is-unavailable':''}"><img src="${storeHtml(product.img)}" alt="${storeHtml(product.n)}" loading="lazy" width="112" height="96"><div class="cart-item-copy"><small>${storeHtml(product.cat)}</small><h3>${storeHtml(product.n)}</h3><span>${old}<b>${productPriceText(product)}</b></span>${unavailable?'<em>Indisponível para compra online</em>':''}<div class="cart-quantity" aria-label="Quantidade"><button type="button" onclick="changeCartQuantity(${product.id},-1)" aria-label="Diminuir quantidade">−</button><output>${item.qty}</output><button type="button" onclick="changeCartQuantity(${product.id},1)" aria-label="Aumentar quantidade" ${item.qty>=Number(product.stock)?'disabled':''}>+</button><small>Máx. ${Number(product.stock||0)}</small></div></div><strong>${brl(item.qty*Number(product.price||0))}</strong><button class="cart-remove" type="button" onclick="removeCart(${product.id})" aria-label="Remover ${storeHtml(product.n)} da sacola">×</button></article>`}).join('');openDrawer(`<div class="cart-heading"><div><small>SACOLA DE COMPRAS</small><h2>Sua sacola</h2></div><span>${entries.reduce((sum,{item})=>sum+item.qty,0)} item(ns)</span></div>${lines||'<div class="empty">Sua sacola está vazia.<br>Que tal encontrar o móvel perfeito para sua casa?</div>'}${entries.length?`<section class="cart-summary"><span>Subtotal <b>${brl(totals.regular)}</b></span><span>Descontos <b class="discount">− ${brl(totals.discount)}</b></span><span>Frete <b>A calcular</b></span><strong>Total parcial <b>${brl(totals.subtotal)}</b></strong></section>${invalid?'<p class="cart-warning">Revise os itens sem estoque antes de continuar.</p>':''}<button class="cart-online-checkout" type="button" onclick="startCheckout()" ${invalid?'disabled':''}>${storeIcon('bag')}<span><b>CONTINUAR PARA O CHECKOUT</b><small>Entrega, pagamento e confirmação</small></span>${storeIcon('arrow')}</button><button class="cart-whatsapp-checkout" type="button" onclick="buyCartWhatsApp()" ${invalid?'disabled':''}>${storeIcon('whatsapp')}<span><b>COMPRAR SACOLA PELO WHATSAPP</b><small>Enviar todos os produtos para a loja</small></span>${storeIcon('arrow')}</button><p class="checkout-structure-note">O checkout financeiro está em preparação. Nenhuma cobrança será criada nesta apresentação.</p>`:''}`)}
function removeCart(id){cart=cart.filter(x=>x.id!==id);save();openCart();toast('Produto removido')}
let checkoutDraft={step:1,customer:{},delivery:{method:'pickup'},payment:'pix'};
function checkoutProgress(){return `<ol class="checkout-progress">${[['Sacola',0],['Identificação',1],['Entrega',2],['Pagamento',3],['Confirmação',4]].map(([label,step])=>`<li class="${checkoutDraft.step===step?'active':checkoutDraft.step>step?'done':''}"><i>${checkoutDraft.step>step?'✓':step+1}</i><span>${label}</span></li>`).join('')}</ol>`}
function startCheckout(){const entries=cartDetails();if(!entries.length)return toast('Sua sacola está vazia.');if(entries.some(({item,product})=>!productInStock(product)||item.qty>Number(product.stock)||product.cartEnabled===false))return toast('Revise a disponibilidade dos itens.');checkoutDraft={step:1,customer:checkoutDraft.customer||{},delivery:{method:commerceSettings.pickupEnabled?'pickup':'delivery'},payment:commerceSettings.pixEnabled?'pix':'card'};document.querySelector('#drawer').classList.add('checkout-open');renderCheckout()}
function checkoutBack(){if(checkoutDraft.step<=1)return openCart();checkoutDraft.step--;renderCheckout()}
function saveCheckoutIdentity(event){event.preventDefault();if(!event.currentTarget.reportValidity())return;const data=new FormData(event.currentTarget);checkoutDraft.customer=Object.fromEntries(data);checkoutDraft.step=2;renderCheckout()}
function setCheckoutDelivery(method){checkoutDraft.delivery.method=method;renderCheckout()}
function saveCheckoutDelivery(event){event.preventDefault();if(!event.currentTarget.reportValidity())return;const data=Object.fromEntries(new FormData(event.currentTarget));checkoutDraft.delivery={...data,method:checkoutDraft.delivery.method};checkoutDraft.step=3;renderCheckout()}
function renderCheckout(){const entries=cartDetails(),totals=cartTotals(entries);const providerReady=Boolean(commerceSettings.gatewayProvider&&commerceSettings.onlineSalesEnabled&&(commerceSettings.pixEnabled||commerceSettings.cardEnabled));let content='';if(checkoutDraft.step===1){content=`<form class="checkout-form" onsubmit="saveCheckoutIdentity(event)"><header><small>ETAPA 1 DE 3</small><h2>Quem está comprando?</h2><p>Pedimos somente os dados necessários para o pedido.</p></header><div class="checkout-fields"><label class="full">Nome completo<input name="name" autocomplete="name" required value="${storeHtml(checkoutDraft.customer.name||'')}"></label><label>E-mail<input name="email" type="email" autocomplete="email" required value="${storeHtml(checkoutDraft.customer.email||'')}"></label><label>Telefone / WhatsApp<input name="phone" type="tel" autocomplete="tel" inputmode="tel" required value="${storeHtml(checkoutDraft.customer.phone||'')}"></label>${commerceSettings.requireCpf?`<label class="full">CPF<input name="cpf" inputmode="numeric" autocomplete="off" pattern="[0-9.\\-]{11,14}" required value="${storeHtml(checkoutDraft.customer.cpf||'')}"></label>`:''}</div><footer><button class="checkout-back" type="button" onclick="openCart()">Voltar à sacola</button><button type="submit">Continuar para entrega →</button></footer></form>`}else if(checkoutDraft.step===2){const delivery=checkoutDraft.delivery.method==='delivery';content=`<form class="checkout-form" onsubmit="saveCheckoutDelivery(event)"><header><small>ETAPA 2 DE 3</small><h2>Como você quer receber?</h2><p>Escolha retirada ou entrega antes de revisar o pagamento.</p></header><div class="delivery-options">${commerceSettings.pickupEnabled!==false?`<button type="button" class="${!delivery?'selected':''}" onclick="setCheckoutDelivery('pickup')"><b>⌂ Retirada na loja</b><small>Praça Ricardo Borges, 75 · Centro</small></button>`:''}${commerceSettings.deliveryEnabled?`<button type="button" class="${delivery?'selected':''}" onclick="setCheckoutDelivery('delivery')"><b>▱ Entrega</b><small>Frete conforme CEP e regras da loja</small></button>`:`<button type="button" disabled><b>▱ Entrega</b><small>Será ativada após configurar as regiões</small></button>`}</div>${delivery?`<div class="checkout-fields address-fields"><label>CEP<input name="postal_code" inputmode="numeric" autocomplete="postal-code" required value="${storeHtml(checkoutDraft.delivery.postal_code||'')}"></label><label class="wide">Rua<input name="street" autocomplete="address-line1" required value="${storeHtml(checkoutDraft.delivery.street||'')}"></label><label>Número<input name="number" autocomplete="address-line2" required value="${storeHtml(checkoutDraft.delivery.number||'')}"></label><label>Complemento<input name="complement" autocomplete="address-line3" value="${storeHtml(checkoutDraft.delivery.complement||'')}"></label><label>Bairro<input name="neighborhood" required value="${storeHtml(checkoutDraft.delivery.neighborhood||'')}"></label><label>Cidade<input name="city" autocomplete="address-level2" required value="${storeHtml(checkoutDraft.delivery.city||'')}"></label><label>Estado<input name="state" autocomplete="address-level1" maxlength="2" required value="${storeHtml(checkoutDraft.delivery.state||'')}"></label></div>`:`<div class="pickup-card"><b>Retirada no Atacarejo dos Móveis</b><span>Praça Ricardo Borges, 75 · Centro · Ribeira do Pombal - BA</span><small>Você receberá a orientação de retirada quando o pedido estiver pronto.</small></div>`}<footer><button class="checkout-back" type="button" onclick="checkoutBack()">← Voltar</button><button type="submit">Revisar pagamento →</button></footer></form>`}else{const delivery=checkoutDraft.delivery.method==='delivery';content=`<div class="checkout-form checkout-payment"><header><small>ETAPA 3 DE 3</small><h2>Pagamento e resumo</h2><p>Confira tudo antes de criar a cobrança.</p></header><div class="checkout-review"><section><h3>Forma de pagamento</h3><div class="payment-options"><label class="${commerceSettings.pixEnabled?'':'disabled'}"><input type="radio" name="previewPayment" ${checkoutDraft.payment==='pix'?'checked':''} ${commerceSettings.pixEnabled?'':'disabled'}><span><b>PIX</b><small>QR Code e Copia e Cola após integração</small></span></label><label class="${commerceSettings.cardEnabled?'':'disabled'}"><input type="radio" name="previewPayment" ${checkoutDraft.payment==='card'?'checked':''} ${commerceSettings.cardEnabled?'':'disabled'}><span><b>Cartão de crédito</b><small>Parcelamento seguro pelo provedor</small></span></label></div><div class="gateway-pending"><b>Integração financeira pendente</b><p>O gateway ainda não foi escolhido. Nenhum PIX, cartão ou pagamento demonstrativo será gerado.</p></div></section><section class="checkout-order-summary"><h3>Resumo do pedido</h3>${entries.map(({item,product})=>`<div><span>${item.qty}× ${storeHtml(product.n)}</span><b>${brl(item.qty*product.price)}</b></div>`).join('')}<hr><div><span>Subtotal</span><b>${brl(totals.regular)}</b></div><div><span>Descontos</span><b>− ${brl(totals.discount)}</b></div><div><span>Frete</span><b>${delivery?'A calcular no backend':brl(0)}</b></div><strong><span>Total ${delivery?'parcial':''}</span><b>${brl(totals.subtotal)}</b></strong></section></div><footer><button class="checkout-back" type="button" onclick="checkoutBack()">← Voltar</button><button type="button" disabled>${providerReady?'Continuar para o gateway':'Aguardando configuração do gateway'}</button></footer><button class="checkout-whatsapp-alternative" type="button" onclick="buyCartWhatsApp()">Prefere finalizar agora? Comprar pelo WhatsApp</button></div>`}openDrawer(`<div class="checkout-shell">${checkoutProgress()}${content}</div>`);document.querySelector('#drawer').classList.add('checkout-open')}
function openAccount(){window.MobileNav?.mark('conta');openDrawer('<h2>Minha conta</h2><p style="color:#66758c">Entre para acompanhar pedidos e salvar seus favoritos.</p><label class="drawer-field" for="accountEmail"><span>Seu e-mail</span><input id="accountEmail" type="email" inputmode="email" autocomplete="email" placeholder="voce@exemplo.com"></label><button class="btn blue drawer-submit" type="button" onclick="toast(\'A área do cliente será ativada com o checkout.\')">Continuar</button><a class="admin-link" href="admin.html">Acessar painel administrativo →</a>')};function openAdmin(){openDrawer('<h2>Painel administrativo</h2><p style="color:#66758c">Gestão de produtos, conteúdo e pedidos da loja.</p><a class="btn blue drawer-submit" href="admin.html">Abrir painel administrativo</a>')};function openWhatsApp(){openWhatsAppMessage(commerceSettings.message)};function scrollToTop(){window.MobileNav?.mark('inicio');window.scrollTo({top:0,behavior:'smooth'})}
const search=document.querySelector('#search');search.addEventListener('input',()=>{let q=normaliseSearch(search.value);let s=document.querySelector('#suggestions');if(!q){s.style.display='none';search.setAttribute('aria-expanded','false');renderCatalog();return}activeCat='Todas';activeEnvironment='Todas';activeSubcategory='';offersOnly=false;let hits=products.filter(p=>normaliseSearch(p.searchTerms||'').includes(q)).slice(0,6);s.innerHTML=hits.map(p=>`<button class="suggestion" type="button" role="option" data-search-product="${p.id}"><b>${storeHtml(p.n)}</b><small>${storeHtml([p.environment,p.subcategory].filter(Boolean).join(' › '))} · ${productPriceText(p)}</small></button>`).join('');s.querySelectorAll('[data-search-product]').forEach(button=>button.onclick=()=>{const product=products.find(item=>item.id===Number(button.dataset.searchProduct));if(!product)return;search.value=product.n;search.setAttribute('aria-expanded','false');s.style.display='none';renderCatalog();document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'})});s.style.display=hits.length?'block':'none';search.setAttribute('aria-expanded',hits.length?'true':'false');renderCatalog()});document.querySelector('#sort').addEventListener('change',renderCatalog);document.querySelector('#cartBtn').onclick=openCart;document.querySelector('#accountBtn').onclick=openAccount;document.querySelector('#favBtn').onclick=()=>{activeCat='Todas';activeEnvironment='Todas';activeSubcategory='';document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'});document.querySelector('#search').value='';document.querySelector('#catalogGrid').innerHTML=(products.filter(p=>favs.includes(p.id)).map(card).join('')||'<div class="empty">Você ainda não favoritou nenhum produto.</div>')};document.querySelector('#drawer').addEventListener('click',e=>{if(e.target.id==='drawer')closeDrawer()});renderEnvironmentNavigation();renderCats();initCategoryCarousel();render();
document.querySelector('#filterToggle').onclick=()=>document.querySelector('#filterPills').classList.toggle('show');
document.querySelectorAll('[data-store-whatsapp]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();openWhatsApp()}));
let cepLookupController=null,cepLookupTimer=null;
function formatCep(value){const digits=String(value||'').replace(/\D/g,'').slice(0,8);return digits.length>5?`${digits.slice(0,5)}-${digits.slice(5)}`:digits}
function setCepResult(type,title,address='',detail=''){
 const result=document.querySelector('#cepResult');if(!result)return;
 result.hidden=false;result.className=`cep-result ${type}`;
 result.querySelector('strong').textContent=title;
 result.querySelector('[data-cep-address]').textContent=address;
 result.querySelector('[data-cep-detail]').textContent=detail;
}
async function lookupCep(){
 const input=document.querySelector('#productCep'),button=document.querySelector('[data-cep-submit]');if(!input||!button)return;
 const cep=input.value.replace(/\D/g,'');input.value=formatCep(cep);
 if(!/^\d{8}$/.test(cep)){setCepResult('error','Digite um CEP válido com 8 números.');input.setAttribute('aria-invalid','true');return}
 input.removeAttribute('aria-invalid');cepLookupController?.abort();cepLookupController=new AbortController();
 button.disabled=true;button.textContent='Buscando…';setCepResult('loading','Buscando endereço…');
 try{
  const response=await fetch(`https://viacep.com.br/ws/${cep}/json/`,{signal:cepLookupController.signal});
  if(!response.ok)throw new Error('request');
  const data=await response.json();if(data.erro){setCepResult('error','CEP não encontrado.','Confira os números e tente novamente.');return}
  const street=[data.logradouro,data.complemento].filter(Boolean).join(', ');
  const city=[data.localidade,data.uf].filter(Boolean).join(' - ');
  const address=[street,data.bairro].filter(Boolean).join(' · ')||'Endereço localizado';
  setCepResult('success',`CEP ${data.cep||formatCep(cep)}`,address,city);
 }catch(error){
  if(error.name!=='AbortError')setCepResult('error','Não foi possível consultar o CEP.','Verifique sua conexão e tente novamente.');
 }finally{
  if(button){button.disabled=false;button.textContent='Calcular'}
 }
}
function setupCepLookup(){
 const input=document.querySelector('#productCep');if(!input)return;
 input.addEventListener('input',()=>{
  input.value=formatCep(input.value);input.removeAttribute('aria-invalid');clearTimeout(cepLookupTimer);
  const result=document.querySelector('#cepResult');if(input.value.replace(/\D/g,'').length<8&&result)result.hidden=true;
  if(input.value.replace(/\D/g,'').length===8)cepLookupTimer=setTimeout(lookupCep,250);
 });
 input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();clearTimeout(cepLookupTimer);lookupCep()}});
}
function openProduct(id){
 const p=products.find(x=>x.id===id);if(!p)return;
 const images=[p.img,...(p.images||[])].filter(Boolean);let i=0;
 const rating=Number.isFinite(p.rating)&&Number.isFinite(p.reviews)?`<div class="detail-rating">${'★'.repeat(Math.round(p.rating))} <span>(${p.reviews} avaliações)</span></div>`:'';
 const stockMessage=productInStock(p)?`${p.stock} unidade${p.stock!==1?'s':''} disponível${p.stock!==1?'eis':''}`:'Indisponível no momento';
 const code=productCode(p);
 const hasPrice=productHasPrice(p);
 const oldPrice=hasPrice&&Number.isFinite(Number(p.old))&&Number(p.old)>Number(p.price)?`<del>${brl(p.old)}</del>`:'';
 const installment=hasPrice&&Number.isFinite(p.installmentCount)&&Number.isFinite(p.installmentValue)&&p.installmentCount>0&&p.installmentValue>0?`<span>ou ${p.installmentCount}x de ${brl(p.installmentValue)}</span>`:'';
 const specifications=productSpecificationEntries(p);
 const draw=()=>{
  const description=p.fullDescription||p.description||`O produto ${p.n.toLowerCase()} traz uma nova possibilidade para o seu ambiente.`;
  openDrawer(`<div class="product-detail-breadcrumb">Início &nbsp;/&nbsp; ${storeHtml(p.environment||'Móveis')} &nbsp;/&nbsp; ${storeHtml(p.subcategory||p.cat)} &nbsp;/&nbsp; ${storeHtml(p.n)}</div><div class="product-detail"><div class="detail-gallery"><button class="detail-main" type="button" aria-label="Ampliar foto ${i+1} de ${images.length}"><img src="${storeHtml(images[i])}" alt="${storeHtml(p.n)}" width="900" height="700"></button><small>Toque ou clique na imagem para ampliar.</small>${images.length>1?`<div class="detail-thumbs" aria-label="Fotos do produto">${images.map((src,n)=>`<button class="detail-thumb ${n===i?'active':''}" type="button" data-detail-image="${n}" aria-label="Mostrar foto ${n+1} de ${images.length}" aria-current="${n===i?'true':'false'}"><img src="${storeHtml(src)}" alt="Foto ${n+1} de ${storeHtml(p.n)}" loading="lazy" width="120" height="90"></button>`).join('')}</div>`:''}</div><div class="detail-info"><div class="detail-actions">↗ Compartilhar&nbsp;&nbsp; ♡ Favoritar</div><small class="detail-badge">${CategoryIcons.icon(p.categoryIconKey||p.subcategory||p.environment||p.cat,{environment:p.environment,size:20})}${storeHtml(p.cat)}</small><h2>${storeHtml(p.n)}</h2>${code?`<p class="detail-code">Código: ${storeHtml(code)}</p>`:''}${rating}<div class="detail-price">${oldPrice}<strong class="${hasPrice?'':'price-on-request'}">${productPriceText(p)}</strong>${installment}</div>${productBenefitSeals(p)?`<div class="detail-benefit-seals" aria-label="Benefícios do produto">${productBenefitSeals(p)}</div>`:''}<p class="detail-payment">${hasPrice?'Preço à vista · consulte condições com a loja':'Fale com a loja para consultar as condições'}</p><p class="detail-stock ${productInStock(p)?'':'is-unavailable'}">${stockMessage}</p><div class="detail-commerce-actions">${productWhatsAppButton(p,true)}${p.cartEnabled!==false&&hasPrice&&productInStock(p)?`<button class="product-add-bag detail-add-bag" type="button" onclick="addCart(${p.id})">${storeIcon('bag')}<span>Adicionar à sacola</span></button>`:''}</div><button class="detail-cart-link" type="button" onclick="openCart()">Ir para minha sacola&nbsp; →</button><hr><p>🚚 &nbsp;Calcule a entrega</p><div class="cep-row"><label class="sr-only" for="productCep">CEP</label><input id="productCep" type="text" inputmode="numeric" autocomplete="postal-code" pattern="[0-9-]*" maxlength="9" aria-label="CEP" aria-describedby="cepResult" placeholder="00000-000"><button class="btn" type="button" data-cep-submit onclick="lookupCep()">Calcular</button></div><div id="cepResult" class="cep-result" role="status" aria-live="polite" hidden><span class="cep-result-pin" aria-hidden="true">⌖</span><div><strong></strong><span data-cep-address></span><small data-cep-detail></small></div></div><small class="cep-helper">Digite os 8 números do CEP para localizar o endereço.</small><p class="detail-safe">♢ &nbsp;A finalização do atendimento é feita diretamente com a loja.</p></div></div><section class="detail-description"><h3>Conheça o produto</h3><p>${storeHtml(description)}</p>${specifications.length?`<dl class="detail-specifications">${specifications.map(([label,value])=>`<div><dt>${storeHtml(label)}</dt><dd>${storeHtml(value)}</dd></div>`).join('')}</dl>`:''}</section></div>`);
  document.querySelector('#drawer').classList.add('product-detail-open');
  document.querySelector('.detail-main').onclick=()=>openLightbox(p.id,i);
  document.querySelectorAll('[data-detail-image]').forEach(button=>button.onclick=()=>{i=Number(button.dataset.detailImage);const main=document.querySelector('.detail-main');main.querySelector('img').src=images[i];main.setAttribute('aria-label',`Ampliar foto ${i+1} de ${images.length}`);document.querySelectorAll('[data-detail-image]').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-current',String(active))})});
  setupCepLookup();
 };
 draw();
}
function openLightbox(id,index){const p=products.find(x=>x.id===id);if(!p)return;const imgs=[p.img,...(p.images||[])];let i=index||0,touchStart=0;const returnFocus=document.activeElement;const modal=document.createElement('div');modal.className='image-lightbox';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-label',`Galeria de ${p.n}`);modal.innerHTML=`<button class="lightbox-close" type="button" aria-label="Fechar">×</button><button class="lightbox-prev" type="button" aria-label="Foto anterior">‹</button><img alt="${p.n}" width="1200" height="900"><button class="lightbox-next" type="button" aria-label="Próxima foto">›</button><small>Deslize ou use as setas para navegar · ESC para fechar</small>`;document.body.append(modal);document.body.classList.add('lightbox-open');const image=modal.querySelector('img');const paint=()=>{image.src=imgs[i];modal.querySelector('.lightbox-prev').hidden=imgs.length<2;modal.querySelector('.lightbox-next').hidden=imgs.length<2};const previous=()=>{i=(i-1+imgs.length)%imgs.length;paint()};const next=()=>{i=(i+1)%imgs.length;paint()};paint();const close=()=>{modal.remove();document.body.classList.remove('lightbox-open');document.removeEventListener('keydown',key);returnFocus?.focus?.()};const key=e=>{if(e.key==='Escape')close();if(e.key==='ArrowLeft')previous();if(e.key==='ArrowRight')next()};modal.onclick=e=>{if(e.target===modal)close()};modal.addEventListener('touchstart',e=>{touchStart=e.changedTouches[0].clientX},{passive:true});modal.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-touchStart;if(Math.abs(delta)>50)(delta>0?previous:next)()},{passive:true});modal.querySelector('.lightbox-close').onclick=close;modal.querySelector('.lightbox-prev').onclick=previous;modal.querySelector('.lightbox-next').onclick=next;document.addEventListener('keydown',key);modal.querySelector('.lightbox-close').focus()}
document.addEventListener('click',e=>{const productCard=e.target.closest('.catalog-card,.product-card');if(productCard&&!e.target.closest('button')){const p=products.find(x=>x.id===Number(productCard.dataset.productId));if(p)openProduct(p.id)}});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.catalog-card,.product-card')){e.preventDefault();const p=products.find(x=>x.id===Number(e.target.dataset.productId));if(p)openProduct(p.id)}});
// Responsive navigation and filters reuse the same product state.
function openNavigation(){openDrawer(`<h2>Explore por ambiente</h2><div class="drawer-environment-list">${environmentNavigation.map(environment=>`<details><summary>${environmentIcon(environment,26)}<span>${storeHtml(environment.name)}</span></summary><div>${environment.subcategories.map(subcategory=>`<button type="button" data-drawer-environment="${storeHtml(environment.name)}" data-drawer-subcategory="${storeHtml(subcategoryName(subcategory))}">${subcategoryIcon(subcategory,environment,24)}<span class="category-label">${storeHtml(subcategoryName(subcategory))}</span><span class="category-arrow-glyph">→</span></button>`).join('')}<button class="drawer-environment-all" type="button" data-drawer-all="${storeHtml(environment.name)}">Ver todos de ${storeHtml(environment.name)} →</button></div></details>`).join('')}</div><nav class="menu-links drawer-secondary-links" aria-label="Atalhos da loja"><button type="button" onclick="closeDrawer();showOffers()">Ofertas</button><button type="button" onclick="openAccount()">Minha conta</button><button type="button" onclick="closeDrawer();document.querySelector('#favBtn').click()">Favoritos</button><button type="button" onclick="openWhatsApp()">Atendimento</button></nav>`);document.querySelectorAll('[data-drawer-subcategory]').forEach(button=>button.onclick=()=>{closeDrawer();filterSubcategory(button.dataset.drawerEnvironment,button.dataset.drawerSubcategory)});document.querySelectorAll('[data-drawer-all]').forEach(button=>button.onclick=()=>{closeDrawer();filterEnvironment(button.dataset.drawerAll)});document.querySelector('.menu')?.setAttribute('aria-expanded','true')}
document.querySelector('.menu').onclick=openNavigation;
document.querySelector('#filterToggle').onclick=openNavigation;
document.querySelector('#searchBtn').onclick=()=>{document.querySelector('#suggestions').style.display='none';search.blur();renderCatalog();document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'})};
search.addEventListener('keydown',e=>{if(e.key==='Enter')document.querySelector('#searchBtn').click()});
document.addEventListener('keydown',e=>{const drawer=document.querySelector('#drawer');if(e.key==='Escape'&&drawer.classList.contains('open'))closeDrawer();if(e.key==='Tab'&&drawer.classList.contains('open')&&!drawer.classList.contains('mobile-route-drawer')){const focusable=[...drawer.querySelectorAll('button:not([disabled]),a[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(el=>el.offsetParent!==null);if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});window.addEventListener('popstate',()=>{if(window.MobileNav)window.MobileNav.handlePopState();else if(document.querySelector('#drawer').classList.contains('open'))closeDrawer(true)});
const footerInfo={
 about:{title:'Sobre nós',body:'O Atacarejo dos Móveis está em Ribeira do Pombal para ajudar você a transformar cada ambiente com variedade, atendimento próximo e condições facilitadas.'},
 store:{title:'Nossa loja',body:'Visite-nos na Praça Ricardo Borges, 75, próximo à Igreja Velha, no Centro de Ribeira do Pombal - BA. CEP 48400-000.'},
 privacy:{title:'Política de privacidade',body:'Seus dados são tratados com cuidado e utilizados somente para viabilizar o atendimento e os serviços solicitados. Para consultar informações específicas, fale com a nossa equipe.'},
 terms:{title:'Termos de uso',body:'Imagens, preços e condições deste ambiente são demonstrativos. Consulte a equipe da loja para confirmar disponibilidade, medidas, prazos e condições comerciais vigentes.'},
 help:{title:'Central de ajuda',body:'Precisa de ajuda para escolher um produto, entender uma condição ou acompanhar um atendimento? Nossa equipe está disponível pelo WhatsApp.'},
 returns:{title:'Trocas e devoluções',body:'As condições de troca e devolução podem variar conforme o produto e a compra. Fale com a nossa equipe e tenha em mãos os dados do pedido.'},
 delivery:{title:'Entrega e prazos',body:'Prazos e disponibilidade de entrega dependem do produto e do endereço. Consulte nossa equipe para receber uma previsão atualizada.'}
};
document.querySelectorAll('[data-footer-info]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();const item=footerInfo[link.dataset.footerInfo];if(item)openDrawer(`<div class="footer-info-dialog"><h2>${item.title}</h2><p>${item.body}</p><button class="btn blue" onclick="closeDrawer();openWhatsApp()">Falar com a equipe</button></div>`)}));
document.querySelector('[data-youtube-placeholder]')?.addEventListener('click',()=>toast('Canal do YouTube em breve.'));

function catalogCard(p){return officialProductCard(p)}
const categoryButton=document.querySelector('#categoriesMenu');
categoryButton.onclick=event=>{event.stopPropagation();const mega=document.querySelector('#environmentMegaMenu');if(mega&&!mega.hidden&&mega.dataset.environment==='all')closeEnvironmentNavigation();else openDesktopAllEnvironmentsMenu()};
document.querySelector('.environment-desktop-nav')?.addEventListener('mouseenter',()=>clearTimeout(environmentMenuTimer));
document.querySelector('.environment-desktop-nav')?.addEventListener('mouseleave',scheduleEnvironmentMenuClose);
document.querySelector('#environmentMegaMenu')?.addEventListener('mouseenter',()=>clearTimeout(environmentMenuTimer));
document.querySelector('#environmentMegaMenu')?.addEventListener('mouseleave',scheduleEnvironmentMenuClose);
document.addEventListener('click',event=>{if(!event.target.closest('.environment-desktop-nav,#environmentMegaMenu'))closeEnvironmentNavigation()});

