const benefitsSection=document.createElement('section'); benefitsSection.className='benefits reference-benefits'; benefitsSection.innerHTML='<div><b>▱</b><span>Entrega Rápida<small>para toda a região</small></span></div><div><b>✥</b><span>Móveis de Qualidade<small>com garantia</small></span></div><div><b>▣</b><span>Pagamento Facilitado<small>até 12x no cartão</small></span></div><div><b>◉</b><span>Atendimento Especializado<small>para te ajudar sempre</small></span></div>'; const catalogSection=document.querySelector('#catalogo'); if(catalogSection) catalogSection.after(benefitsSection);
